// Calendar events from upstream
const events = $('Get Today\'s Events').all();
const lines = [];

for (const item of events) {
  const ev = item.json;
  // Skip empty items (alwaysOutputData sends one empty item when no events)
  if (!ev.summary && !ev.start) continue;

  const start = ev.start?.dateTime || ev.start?.date || '';
  const end = ev.end?.dateTime || ev.end?.date || '';

  // Format times (HH:MM)
  let timeRange = '';
  if (start.includes('T')) {
    const s = new Date(start);
    const e = new Date(end);
    const fmt = (d) => d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false });
    timeRange = `${fmt(s)}-${fmt(e)}`;
  } else {
    timeRange = 'All day';
  }

  lines.push(`${timeRange}  ${ev.summary || '(no title)'}`);
}

const calendarBlock = lines.length > 0
  ? lines.join('\n')
  : 'No events today';

// Price section from price-checker. Read by node name, not $input: the two
// Sheets reads now sit between Check Prices and this node.
const priceSection = $('Check Prices').first().json.priceSection || '';

// --- Site digest ----------------------------------------------------------
// Your own public IPs. Anything listed here is counted separately and kept out
// of the visitor totals — otherwise your own browsing is the most engaged
// visitor on the site every single day. Loopback and private ranges never
// reach the sheet at all; /api/track drops them.
// Residential addresses rotate. If your own browsing starts showing up as a
// stranger from your own city, find the address in the Visits sheet and add it
// here — in the n8n UI, never in the public repo copy of this workflow.
const SELF_IPS = []; // set on the live instance — never commit real IPs

// Telegram renders this with parse_mode HTML and everything below is
// visitor-supplied (link labels, use cases, emails). Escape all of it, or one
// stray '<' silently kills the whole message.
const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const clip = (v, n) => {
  const s = String(v ?? '').trim();
  return s.length > n ? s.slice(0, n - 1) + '…' : s;
};

// The beacon stores clicks as "label → href". The href is for the sheet and
// /visits; in a summary the label alone is what reads.
const label = (target) => String(target ?? '').split(' → ')[0].trim();

const cutoff = Date.now() - 24 * 60 * 60 * 1000;
const fresh = (value) => {
  const t = Date.parse(value);
  return Number.isFinite(t) && t >= cutoff;
};

// Rank a {key: count} tally and render the top n as "key · count" lines.
const topOf = (tally, n) => Object.entries(tally)
  .sort((a, b) => b[1] - a[1])
  .slice(0, n);

const rows = $('Get Visits').all()
  .map((i) => i.json)
  .filter((r) => r.ip && fresh(r.ts));

const mine = rows.filter((r) => SELF_IPS.includes(r.ip));
const theirs = rows.filter((r) => !SELF_IPS.includes(r.ip));

const visitors = new Map();
const pages = {};
const countries = {};
let views = 0;
let clicks = 0;

for (const r of theirs) {
  let v = visitors.get(r.ip);
  if (!v) {
    v = { where: [r.city, r.country].filter(Boolean).join(', '), views: 0, clicks: [] };
    visitors.set(r.ip, v);
  }
  if (r.event === 'pageview') {
    views += 1;
    v.views += 1;
    if (r.path) pages[r.path] = (pages[r.path] || 0) + 1;
    if (r.country) countries[r.country] = (countries[r.country] || 0) + 1;
  } else if (r.event === 'click') {
    clicks += 1;
    const l = label(r.target);
    if (l && !v.clicks.includes(l)) v.clicks.push(l);
  }
}

// The site block ALWAYS renders, even on a dead-quiet day. A missing section is
// indistinguishable from a broken pipeline, and that ambiguity cost real
// confusion the first morning this shipped: no visitors looked like no feature.
const parts = [`\n\n👀 <b>SITE</b> · last 24h`];
let siteSection = '';

if (visitors.size === 0) {
  parts.push(mine.length
    ? `\nNo outside visitors (you: ${mine.length} event${mine.length === 1 ? '' : 's'})`
    : '\nNo visitors');
  siteSection = parts.join('');
} else {
  parts.push(`\n${visitors.size} visitor${visitors.size === 1 ? '' : 's'} · ${views} view${views === 1 ? '' : 's'} · ${clicks} click${clicks === 1 ? '' : 's'}`);

  const topPages = topOf(pages, 5);
  if (topPages.length) {
    parts.push('\n\nTop pages');
    for (const [path, n] of topPages) parts.push(`\n  ${esc(clip(path, 40))} · ${n}`);
  }

  const topCountries = topOf(countries, 5);
  if (topCountries.length) {
    parts.push('\n\nFrom\n  ' + topCountries.map(([c, n]) => `${esc(c)} ${n}`).join(' · '));
  }

  // Only visitors who did more than bounce are worth naming.
  const engaged = [...visitors.values()]
    .filter((v) => v.views > 1 || v.clicks.length > 0)
    .sort((a, b) => b.views - a.views || b.clicks.length - a.clicks.length)
    .slice(0, 3);
  if (engaged.length) {
    parts.push('\n\nMost engaged');
    for (const v of engaged) {
      parts.push(`\n  ${esc(v.where || 'unknown')} — ${v.views} view${v.views === 1 ? '' : 's'}`);
      if (v.clicks.length) {
        parts.push(`\n    clicked ${v.clicks.slice(0, 2).map((c) => `“${esc(clip(c, 30))}”`).join(', ')}`);
      }
    }
  }

  if (mine.length) parts.push(`\n\n(you: ${mine.length} event${mine.length === 1 ? '' : 's'}, not counted)`);
  // Points at the sheet, not a /visits command — that command does not exist
  // yet. When it is added to the menu-handler registry, swap this line.
  if (visitors.size > engaged.length) parts.push(`\n\n→ full detail in the Visits sheet`);
  siteSection = parts.join('');
}

// Signups: the Signups sheet is upserted on email, so a row is one person.
const signupRows = $('Get Signups').all()
  .map((i) => i.json)
  .filter((r) => r.email);
const freshSignups = signupRows.filter((r) => fresh(r.signup_timestamp));
let signupSection = '';

if (freshSignups.length > 0) {
  const listed = freshSignups.map((r) => {
    const name = [r.first_name, r.surname].filter(Boolean).join(' ').trim();
    const who = name ? esc(name) : esc(r.email);
    const why = r.use_case ? ` — ${esc(clip(r.use_case, 50))}` : '';
    return `\n  ${who}${why}`;
  }).join('');
  signupSection = `\n\n🌱 <b>WAITLIST</b> · ${freshSignups.length} new (${signupRows.length} total)${listed}`;
}

// --- Plugin sections ------------------------------------------------------
// Sections installed through the seam. A registry entry names a subworkflow,
// Run Plugin executes each, and each returns { key, icon, title, blocks, actions }.
// Rendering is generic: this node does not know what a commitment is.
//
// Matching is by KEY, never by position. A plugin that threw comes back as an
// error item with no key, so any registry key missing from the results is a
// failure we can still name — which is what makes continueOnFail worth having.
// Escaping happens HERE, centrally: plugins return plain text so that one
// forgotten esc() in any project cannot kill the whole sendMessage.
const registry = $('Plugins').all().map((i) => i.json).filter((r) => r && r.enabled);
const returned = new Map(
  $('Run Plugin').all().map((i) => i.json).filter((p) => p && p.key).map((p) => [p.key, p]),
);

const actions = [];

const pluginSections = registry
  .slice()
  .sort((a, b) => (a.order || 0) - (b.order || 0))
  .map((r) => {
    const p = returned.get(r.key);
    if (!p) return `\n\n⚠️ <b>${esc(String(r.key || '?').toUpperCase())}</b> unavailable`;

    // Collected verbatim and validated downstream in Split Actions — the
    // briefing does not interpret a plugin's buttons, it only carries them.
    for (const a of (Array.isArray(p.actions) ? p.actions : [])) {
      if (a && a.text && Array.isArray(a.buttons) && a.buttons.length) actions.push(a);
    }

    const head = `\n\n${p.icon || '•'} <b>${esc(p.title || r.key)}</b>`;
    const blocks = (Array.isArray(p.blocks) ? p.blocks : [])
      .filter((b) => b && Array.isArray(b.items) && b.items.length);
    if (!blocks.length) return `${head}\n${esc(p.empty || 'Nothing to report')}`;

    return head + blocks.map((b) => (b.heading ? `\n<b>${esc(b.heading)}</b>` : '')
      + b.items.map((it) => `\n  ${esc(it)}`).join('')).join('');
  })
  .join('');

let message = `☀️ Good morning! Your day:\n${calendarBlock}${pluginSections}${priceSection}${siteSection}${signupSection}`;

// Telegram rejects anything over 4096 characters. Cut on a line boundary so a
// truncation can never split an HTML entity and break parsing.
const LIMIT = 4096;
if (message.length > LIMIT) {
  const cut = message.slice(0, LIMIT - 16);
  message = cut.slice(0, cut.lastIndexOf('\n')) + '\n… (truncated)';
}

return [{ json: { message, actions } }];

// Briefing plugin registry — THE SEAM.
//
// Adding a morning section means adding one line here. Nothing else in this
// workflow changes: Run Plugin dispatches dynamically on workflowId, and
// Format Message renders whatever comes back by key.
//
// 'order' is message position, and it is a real decision rather than cosmetics.
// Telegram hard-caps at 4096 characters and truncates from the TAIL, so anything
// actionable sorts first. A commitments list cut off by a busy traffic day is a
// missed payment.
//
// 'enabled: false' is the kill switch — a misbehaving plugin is switched off in
// one place, with no nodes to unwire.
// date/tz ride on the registry item: the plugin trigger accepts passthrough, so
// whatever is emitted here IS the plugin's input. Named inputs on the trigger
// would strip every other field, which the task-tap path depends on.
const ctx = { date: $now.toFormat('yyyy-MM-dd'), tz: 'Europe/Zurich' };

return [
  { json: { key: 'commitments', order: 20, workflowId: 'ID_COMMITMENTS', enabled: true, ...ctx } },
];

// One message per actionable item, each with its own buttons.
//
// The buttons cannot live on the main briefing message: n8n's Telegram node
// builds its keyboard from a fixedCollection, so the NUMBER of buttons cannot
// vary at runtime. A separate message per action sidesteps that entirely — and
// it makes ticking one item a single-message edit instead of a rebuild of the
// whole briefing.
//
// The 2-slot shape below is the cost of that: an action must supply exactly two
// buttons. Anything else is dropped rather than sent malformed, because Telegram
// rejects the ENTIRE keyboard when one button is invalid.
const actions = $('Format Message').first().json.actions || [];

return actions
  .filter((a) => a && a.text && Array.isArray(a.buttons) && a.buttons.length === 2)
  .map((a) => ({
    json: {
      text: a.text,
      b1label: a.buttons[0].label,
      b1cb: a.buttons[0].cb,
      b2label: a.buttons[1].label,
      b2cb: a.buttons[1].cb,
    },
  }));
